function validate([nums]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 200000) return 'nums needs 2 to 2 * 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -1e9 || v > 1e9)) return 'Each value is a whole number between -10^9 and 10^9.';
  return null;
}

