function maxIncreasingSubarrays(nums) {
  let previous = 0;
  let current = 1;
  let best = 0;
  for (let i = 1; i < nums.length; i++) {
    if (nums[i] > nums[i - 1]) {
      current += 1;
    } else {
      previous = current;
      current = 1;
    }
    best = Math.max(best, Math.floor(current / 2), Math.min(previous, current));
  }
  return best;
}

