function maxIncreasingSubarrays(nums) {
  // Try every k from the largest possible down, and every start a, checking both pieces element by element.
  const increasing = (from, length) => {
    for (let i = from + 1; i < from + length; i++) if (nums[i] <= nums[i - 1]) return false;
    return true;
  };
  for (let k = Math.floor(nums.length / 2); k >= 1; k--) {
    for (let a = 0; a + 2 * k <= nums.length; a++) {
      if (increasing(a, k) && increasing(a + k, k)) return k;
    }
  }
  return 0;
}

