function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const large = size === 'large';
  const n = large ? 2000 : 2 + pick(11);
  const nums = [];
  if (pick(3) === 0) {
    // Plain random values: from a tiny range (many ties and drops) or the full range.
    const span = large ? 1000000000 : 1 + pick(4);
    for (let i = 0; i < n; i++) nums.push(pick(2 * span + 1) - span);
    return [nums];
  }
  // Strictly increasing runs of random lengths; each new run starts at or below the last value.
  const longest = large ? [8, 300, 2000][pick(3)] : 1 + pick(8);
  let value = large ? pick(2000001) - 1000000 : pick(11) - 5;
  while (nums.length < n) {
    const length = 1 + pick(longest);
    for (let j = 0; j < length && nums.length < n; j++) {
      nums.push(value);
      value += 1 + pick(large ? 1000 : 3);
    }
    value = nums[nums.length - 1] - pick(large ? 1000 : 4);
  }
  return [nums];
}
